use std::{collections::BTreeSet,sync::{Arc,Barrier},time::{SystemTime,UNIX_EPOCH}};
fn main(){let barrier=Arc::new(Barrier::new(3));let mut workers=Vec::new();for _ in 0..3 {let barrier=barrier.clone();workers.push(std::thread::spawn(move||{let mut names=Vec::with_capacity(10000);barrier.wait();for _ in 0..10000 {names.push(format!("spiral-storage-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()));}names}));}let all:Vec<String>=workers.into_iter().flat_map(|worker|worker.join().unwrap()).collect();let unique:BTreeSet<&str>=all.iter().map(String::as_str).collect();println!("constructor_calls={} unique_names={} colliding_calls={}",all.len(),unique.len(),all.len()-unique.len());}
